package com.meterflow.credits;
import jakarta.persistence.*;import java.math.*;import java.util.*;
@Entity @Table(name="credit_accounts",uniqueConstraints=@UniqueConstraint(columnNames="customer_id"))
public class CreditAccount{@Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@Column(name="customer_id",nullable=false)private String customerId;@Column(nullable=false,precision=18,scale=2)private BigDecimal balance=BigDecimal.ZERO;@Column(nullable=false)private String currency="BDT";@Version private long version;protected CreditAccount(){}public CreditAccount(String c,String currency){customerId=c;this.currency=currency;}public UUID getId(){return id;}public String getCustomerId(){return customerId;}public BigDecimal getBalance(){return balance;}public String getCurrency(){return currency;}public void add(BigDecimal a){if(a.signum()<=0)throw new IllegalArgumentException("Credit amount must be positive");balance=balance.add(a);}public BigDecimal consume(BigDecimal a){if(a.signum()<0)throw new IllegalArgumentException("Amount cannot be negative");BigDecimal used=balance.min(a);balance=balance.subtract(used);return used;}}
